package ru.urfu.alphamatcher.experiment;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import ru.urfu.alphamatcher.experiment.MatchingModel.*;
class MentionContextRegressionTest {
 static final List<String> EXACT=List.of("\u041f\u043b\u0430\u0442\u0435\u043b\u044c\u0449\u0438\u043a \u041e\u041e\u041e \u00ab\u0412\u0435\u043a\u0442\u043e\u0440\u00bb, \u0418\u041d\u041d 000012345627. \u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443 \u2116 D-018 \u0437\u0430 \u041e\u041e\u041e \u00ab\u041a\u043e\u043d\u0442\u0443\u0440\u00bb, \u0418\u041d\u041d 7707083893. \u0418\u041d\u041d 7707083893 \u0443\u043a\u0430\u0437\u0430\u043d \u043a\u0430\u043a \u0440\u0435\u043a\u0432\u0438\u0437\u0438\u0442 \u0434\u043e\u043b\u0436\u043d\u0438\u043a\u0430, \u0430 \u043d\u0435 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044f \u0434\u0435\u043d\u0435\u0436\u043d\u044b\u0445 \u0441\u0440\u0435\u0434\u0441\u0442\u0432.",
"\u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443 \u2116 F-118 \u043e\u0442 \u0438\u043c\u0435\u043d\u0438 \u0418.\u0418. \u0418\u0432\u0430\u043d\u043e\u0432\u0430. \u0412 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0443\u043a\u0430\u0437\u0430\u043d \u0418\u0432\u0430\u043d\u043e\u0432 \u0418\u0432\u0430\u043d \u041f\u0435\u0442\u0440\u043e\u0432\u0438\u0447, \u0430 \u0432 \u043f\u043b\u0430\u0442\u0435\u0436\u043d\u043e\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u0418\u0432\u0430\u043d\u043e\u0432 \u0418\u0432\u0430\u043d \u0418\u0432\u0430\u043d\u043e\u0432\u0438\u0447. \u041f\u043b\u0430\u0442\u0435\u043b\u044c\u0449\u0438\u043a \u2014 \u041e\u041e\u041e \u00ab\u0412\u0435\u043a\u0442\u043e\u0440\u00bb.",
"\u041e\u043f\u043b\u0430\u0442\u0430 \u0418\u041f \u0418\u0432\u0430\u043d\u043e\u0432\u0443 \u0418\u0432\u0430\u043d\u0443 \u0418\u0432\u0430\u043d\u043e\u0432\u0438\u0447\u0443 \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443 \u0443\u0441\u043b\u0443\u0433 \u2116 88/\u0423-26. \u041f\u043b\u0430\u0442\u0435\u0436 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0438\u043d \u0418\u0432\u0430\u043d\u043e\u0432 \u0418\u0432\u0430\u043d \u0418\u0432\u0430\u043d\u043e\u0432\u0438\u0447 \u0437\u0430 \u041e\u041e\u041e \u00ab\u0412\u0435\u043a\u0442\u043e\u0440\u00bb. \u041f\u043e\u043b\u0443\u0447\u0430\u0442\u0435\u043b\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043a\u0430\u043a \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u044c.");
 private final PurposeParser parser=new PurposeParser();
 @Test void exact7doesNotInventMoneyNameOrPayer(){var f=parser.parse(EXACT.get(0));assertTrue(f.names().isEmpty(),f.toString());assertTrue(f.roleClaims().stream().noneMatch(c->c.kind().equals("NAME")));assertTrue(f.roleClaims().contains(new PurposeParser.RoleClaim("INN","000012345627","PAYER")));assertEquals(List.of("D-018"),f.contractNumbers());}
 @Test void exact12retainsInitialsAndBothConflictingFullNames(){var f=parser.parse(EXACT.get(1));assertTrue(f.names().stream().noneMatch(n->n.surface().startsWith("имени")));for(String name:List.of("И.И. Иванова","Иванов Иван Петрович","Иванов Иван Иванович"))assertTrue(f.names().stream().anyMatch(n->n.surface().equals(name)),f.toString());assertTrue(f.issues().stream().anyMatch(i->i.startsWith("INCOMPLETE_NAME")));}
 @Test void exact13doesNotInventEntrepreneurStatusAsPerson(){var f=parser.parse(EXACT.get(2));assertEquals(List.of("88/У-26."),f.contractNumbers());assertTrue(f.names().stream().noneMatch(n->n.surface().contains("действует")),f.toString());assertTrue(f.roleClaims().stream().noneMatch(c->c.kind().equals("NAME")&&c.value().contains("предприниматель")));}
 @ParameterizedTest @ValueSource(strings={"процентного займа","беспроцентного займа","поручительства","залога","услуг"})
 void typedReferencesAreLiteralAndSafeOnlyWithMatchingParticipants(String type){var f=parser.parse("Договор "+type+" № ZX-583, ИНН 9900000017");assertEquals(List.of("ZX-583"),f.contractNumbers());assertEquals(Status.SAFE,CorrectnessRemediationTest.decide(f.normalized(),List.of(CorrectnessRemediationTest.CONTRACT)).status());}
 @Test void amountsDatesAndSlashesAreNotNewNumbers(){var f=parser.parse("По договорам № А-001/26 от 01.01.2026 на 100 000 руб.; № А-002/26 от 02.01.2026 на 200,50 руб. и № А-003/26 от 03.01.2026 на 300 руб.");assertEquals(List.of("А-001/26","А-002/26","А-003/26"),f.contractNumbers());assertEquals(PurposeParser.Completeness.COMPLETE,f.contractAnalysis(),f.toString());}
 @ParameterizedTest @ValueSource(strings={"Договор № ZX-583 указан ошибочно. Корректное основание - договор № ZZ-2", "Платеж НЕ является исполнением обязательства за третье лицо по договору № ZX-583", "Платеж НЕ относится к договору № ZX-583", "Договор № ZX-583. Это цитата из отмененного письма", "Договор № ZX-583. Предыдущий номер приведен исключительно для идентификации", "Договор № ZX-583. Указанный ИНН ошибочен; фактический ИНН 9900000024"})
 void risksPreserveDiscoveryAndForbidFinancialCertification(String text){var f=parser.parse(text);assertTrue(f.contractSearchNumbers().contains("ZX-583"));assertTrue(f.issues().stream().anyMatch(i->i.startsWith("UNRESOLVED_MENTION_CONTEXT")),f.toString());var d=CorrectnessRemediationTest.decide(text,List.of(CorrectnessRemediationTest.CONTRACT));assertEquals(Status.REVIEW,d.status());assertTrue(d.candidateIds().contains(101L));for(var m:f.mentions()){assertFalse(m.confirmedFact());assertEquals(m.surface(),f.normalized().substring(m.start(),m.end()));}}
 @Test void innDiscussionIsNotMalformedNumericField(){var f=parser.parse("Указанный ИНН ошибочен; фактический ИНН 7707083893");assertEquals(List.of("7707083893"),f.inns());assertTrue(f.issues().stream().noneMatch(i->i.startsWith("INVALID_INN_FORMAT")));}
 @Test void repeatedReferenceDisplayDoesNotChangeSearch(){var f=parser.parse("Договор № D-1. Договор № D-1");assertEquals(List.of("D-1"),f.contractDisplayNumbers());assertEquals(2,f.contractReferences().size());assertTrue(f.contractSearchNumbers().containsAll(List.of("D-1.","D-1")));}
 @Test void sameOrganizationNameDoesNotEraseContradictoryInnRoles(){
  var payer=new Party(1L,"9900000017","9900000017",true,"ООО Вектор","ООО Вектор",null,null,null);var recipient=new Party(2L,"9900000024","9900000024",true,"ООО Вектор","ООО Вектор",null,null,null);var parties=Map.of("PAYER",payer,"RECIPIENT",recipient);
  String text="Договор ZX-583. Плательщик ООО \"Вектор\", ИНН 9900000024. Получатель ООО \"Вектор\", ИНН 9900000017";
  var d=DiscoveryTestSupport.evaluate(new Operation(1,text,"LOADED",true,null,parties),parser.parse(text),List.of(new Candidate(101,"ZX-583",parties)));assertEquals(Status.REVIEW,d.status());assertTrue(d.checks().stream().anyMatch(c->c.code().equals("ROLE_CLAIMS")&&!c.passed()),d.toString());
 }
 @ParameterizedTest @ValueSource(strings={"денежных средств","банковского перевода","выполняет расчет","действует как индивидуальный предприниматель","ожидает уточнения реквизитов"})
 void roleCueAloneDoesNotProvePersonalName(String phrase){var f=parser.parse("Отправитель "+phrase+".");assertTrue(f.names().isEmpty(),f.toString());assertTrue(f.roleClaims().stream().noneMatch(c->c.kind().equals("NAME")));assertFalse(f.issues().isEmpty());}
 @Test void negativeThirdPartyIsNotAnAffirmedFact(){var f=parser.parse("Платеж НЕ является исполнением обязательства за третье лицо");assertEquals(MentionContexts.Context.NEGATED,MentionContexts.thirdPartyContext(f));}
 @Test void whitespaceMetamorphismsKeepAvailableCases(){for(String text:EXACT)for(String space:List.of("\u00a0","\u202f","\t","\n\n")){var a=parser.parse(text);var b=parser.parse(text.replace(" ",space));assertEquals(a,b);}}
}
